(() => {
 const bank=[{"topic":"Basic Periodontology","q":["The periodontium consists of:","Periodontium मा के-के पर्छन्?",["Gingiva, periodontal ligament, cementum and alveolar bone","Enamel, dentin, pulp and tongue","Only gingiva and enamel","Pulp and dentin only"],0,"The periodontium includes four supporting tissues: gingiva, periodontal ligament, cementum and alveolar bone.","Periodontium मा gingiva, periodontal ligament, cementum र alveolar bone गरी चार tissue हुन्छन्।"]},{"topic":"Basic Periodontology","q":["The primary etiological factor in plaque-induced gingivitis is:","Plaque-induced gingivitis को मुख्य कारण के हो?",["Dental biofilm","Tooth shade","Fluoride varnish","Occlusal anatomy"],0,"Dental biofilm is the primary etiological factor in plaque-induced gingivitis.","Dental biofilm नै plaque-induced gingivitis को मुख्य कारण हो।"]},{"topic":"Basic Periodontology","q":["Bleeding on probing is commonly associated with:","Probing गर्दा रगत आउनु कुन अवस्थासँग सम्बन्धित हुन्छ?",["Gingival inflammation","Enamel fracture","Pulp calcification","Tooth eruption"],0,"Bleeding on probing is a clinical sign often associated with gingival inflammation.","Probing गर्दा रगत आउनु gingival inflammation को सामान्य clinical sign हो।"]},{"topic":"Basic Periodontology","q":["Calculus is best described as:","Calculus भन्नाले के बुझिन्छ?",["Mineralized dental plaque","Food debris only","Healthy enamel","Salivary gland tissue"],0,"Calculus is mineralized dental plaque and may retain biofilm on its surface.","Calculus भनेको mineralized dental plaque हो, जसको सतहमा biofilm रहन सक्छ।"]},{"topic":"Basic Periodontology","q":["The main purpose of periodontal probing is to assess:","Periodontal probing को मुख्य उद्देश्य के हो?",["Sulcus or pocket depth","Tooth colour","Pulp vitality only","Crown translucency"],0,"Periodontal probing measures sulcus/pocket depth as part of a full periodontal assessment.","Periodontal probing ले पूर्ण periodontal assessment को भागका रूपमा sulcus/pocket depth नाप्छ।"]},{"topic":"Oral Pathology & Microbiology","q":["Dental caries is a:","Dental caries कस्तो रोग हो?",["Biofilm-mediated, sugar-driven, multifactorial disease","Purely hereditary condition","Viral disease only","Bone fracture"],0,"Dental caries is a multifactorial disease involving biofilm, dietary sugars and host factors.","Dental caries biofilm, खानाको चिनी र host factors सँग सम्बन्धित बहु-कारकीय रोग हो।"]},{"topic":"Oral Pathology & Microbiology","q":["Candida albicans is commonly associated with:","Candida albicans कुन अवस्थासँग सम्बन्धित हुन्छ?",["Oral candidiasis","Dental fluorosis","Periodontal abscess only","Enamel erosion"],0,"Candida species can cause oral candidiasis, particularly when local or systemic factors permit overgrowth.","स्थानीय वा systemic कारणले वृद्धि हुँदा Candida ले oral candidiasis गराउन सक्छ।"]},{"topic":"Oral Pathology & Microbiology","q":["A persistent unexplained oral ulcer requires:","कारण नखुलेको लामो समयको oral ulcer भए के गर्नुपर्छ?",["Timely professional assessment","Home scraping","Ignoring if painless","Routine polishing only"],0,"Persistent ulcers need timely assessment and referral as indicated to exclude significant disease.","लामो समय रहने ulcer को महत्त्वपूर्ण रोग छुट्याउन समयमै जाँच र आवश्यक referral गर्नुपर्छ।"]},{"topic":"Oral Pathology & Microbiology","q":["Which microorganism is strongly associated with dental caries?","Dental caries सँग कुन microorganism सम्बन्धित छ?",["Streptococcus mutans","Candida auris only","Plasmodium vivax","Mycobacterium tuberculosis"],0,"Streptococcus mutans is one of the organisms associated with cariogenic biofilm.","Streptococcus mutans caries गराउने biofilm सँग सम्बन्धित जीवाणुमध्ये एक हो।"]},{"topic":"Oral Pathology & Microbiology","q":["Gingivitis differs from periodontitis because gingivitis:","Gingivitis र periodontitis बीचको फरक के हो?",["Does not involve periodontal attachment loss","Always causes tooth loss","Destroys alveolar bone in every case","Is a pulpal disease"],0,"Gingivitis is inflammation without periodontal attachment loss; periodontitis involves support tissue destruction.","Gingivitis मा periodontal attachment loss हुँदैन; periodontitis मा supporting tissue नष्ट हुन्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["Alginate is commonly used to make:","Alginate सामान्यतया के बनाउन प्रयोग हुन्छ?",["Preliminary impressions","Definitive metal crowns directly","Local anaesthetic","Root canal obturation"],0,"Alginate is an irreversible hydrocolloid commonly used for preliminary impressions.","Alginate preliminary impression का लागि प्रयोग हुने irreversible hydrocolloid हो।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["Which instrument is commonly used to examine tooth surfaces?","दाँतको सतह जाँच्न कुन instrument प्रयोग हुन्छ?",["Mouth mirror","Amalgam carrier","Burnisher only","Extraction forceps"],0,"A mouth mirror provides indirect vision, retraction and illumination assistance.","Mouth mirror ले indirect vision, retraction र प्रकाशमा सहयोग गर्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["Glass ionomer cement chemically bonds to:","Glass ionomer cement रासायनिक रूपमा कुनसँग जोडिन्छ?",["Tooth structure","Stainless steel only","Rubber dam only","Cotton roll"],0,"Glass ionomer can chemically bond to enamel and dentin through ionic interaction.","Glass ionomer ionic interaction मार्फत enamel र dentin सँग रासायनिक रूपमा जोडिन सक्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["The purpose of a matrix band is to:","Matrix band को उद्देश्य के हो?",["Provide a temporary wall for a restoration","Measure blood pressure","Remove calculus","Take radiographs"],0,"A matrix band helps shape and contain restorative material, especially in proximal restorations.","Matrix band ले विशेषगरी proximal restoration गर्दा restorative material लाई आकार र सीमा दिन्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["A dental assistant should pass instruments:","Dental assistant ले instrument कसरी pass गर्नुपर्छ?",["Safely within the operator's visual field and agreed technique","By throwing them","With working ends pointed toward the patient","Without communication"],0,"Safe instrument transfer uses an agreed technique and avoids injury to the patient and team.","सुरक्षित instrument transfer मा सहमत technique प्रयोग गरी बिरामी र टोलीलाई चोट लाग्नबाट बचाइन्छ।"]},{"topic":"Oral Anatomy & Physiology","q":["The hardest substance in the human body is:","मानव शरीरको सबैभन्दा कडा पदार्थ कुन हो?",["Enamel","Dentin","Cementum","Bone"],0,"Enamel is the hardest tissue in the human body.","Enamel मानव शरीरको सबैभन्दा कडा tissue हो।"]},{"topic":"Oral Anatomy & Physiology","q":["The permanent dentition normally contains:","स्थायी दाँत सामान्यतया कति हुन्छन्?",["32 teeth including third molars","20 teeth","24 teeth","28 teeth in every person"],0,"The complete permanent dentition has 32 teeth including third molars, though third molars may be absent.","तेस्रो molar सहित पूर्ण स्थायी दाँत ३२ हुन्छन्, तर सबैमा तेस्रो molar नहुन सक्छ।"]},{"topic":"Oral Anatomy & Physiology","q":["The primary function of the periodontal ligament is to:","Periodontal ligament को मुख्य काम के हो?",["Attach tooth to alveolar bone and absorb functional forces","Produce enamel","Secrete saliva","Form the dental pulp"],0,"The periodontal ligament connects cementum to alveolar bone and helps distribute occlusal forces.","Periodontal ligament ले cementum लाई alveolar bone सँग जोड्छ र चपाउँदाको बल बाँड्छ।"]},{"topic":"Oral Anatomy & Physiology","q":["The largest salivary gland is the:","सबैभन्दा ठूलो salivary gland कुन हो?",["Parotid gland","Sublingual gland","Submandibular gland","Labial gland"],0,"The parotid is the largest major salivary gland.","Parotid सबैभन्दा ठूलो major salivary gland हो।"]},{"topic":"Oral Anatomy & Physiology","q":["The tongue is primarily involved in:","जिब्रो मुख्यतया कुन काममा संलग्न हुन्छ?",["Taste, speech and food manipulation","Hearing","Vision","Blood filtration"],0,"The tongue contributes to taste, speech, swallowing and manipulation of food.","जिब्रोले स्वाद, बोली, निल्ने प्रक्रिया र खाना चलाउन मद्दत गर्छ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["The primary aim of oral health education is to:","मुख स्वास्थ्य शिक्षाको मुख्य उद्देश्य के हो?",["Improve knowledge and support healthy behaviours","Replace all dental treatment","Increase sugar consumption","Avoid preventive care"],0,"Oral health education supports informed choices and healthier behaviours.","मुख स्वास्थ्य शिक्षाले सही निर्णय र स्वस्थ व्यवहार अपनाउन सहयोग गर्छ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["A school-based fluoride programme is an example of:","विद्यालयमा fluoride कार्यक्रम कुन प्रकारको रोकथाम हो?",["Community preventive intervention","Individual surgery","Emergency treatment","Prosthodontic treatment"],0,"School fluoride programmes are population-based preventive interventions when appropriately designed.","उचित रूपमा सञ्चालन गरिएको school fluoride programme समुदायस्तरको रोकथाम हो।"]},{"topic":"Dental Public Health & Community Dentistry","q":["Primary prevention aims to:","Primary prevention को उद्देश्य के हो?",["Prevent disease before it occurs","Treat advanced complications only","Rehabilitate after tooth loss","Diagnose cancer only"],0,"Primary prevention reduces risk and prevents disease onset.","Primary prevention ले जोखिम घटाएर रोग सुरु हुन नदिन मद्दत गर्छ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["Which is an example of health promotion?","Health promotion को उदाहरण कुन हो?",["Teaching effective toothbrushing and healthy diet","Extracting all teeth","Prescribing antibiotics to everyone","Avoiding community participation"],0,"Health promotion empowers people to improve control over health through education and supportive environments.","Health promotion ले शिक्षा र सहयोगी वातावरणबाट मानिसलाई आफ्नो स्वास्थ्य सुधार्न सक्षम बनाउँछ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["A community oral health survey should use:","समुदायको मुख स्वास्थ्य सर्वेक्षणमा के प्रयोग गर्नुपर्छ?",["Standardized methods and defined sampling","Only random opinions","Unrecorded observations","Different criteria for each person"],0,"Standardized methods and sampling improve consistency and interpretability.","Standardized विधि र sampling ले नतिजा तुलना र व्याख्या गर्न सजिलो बनाउँछ।"]},{"topic":"Dental Radiography & Photography","q":["ALARA means radiation exposure should be:","ALARA अनुसार radiation exposure कस्तो हुनुपर्छ?",["As low as reasonably achievable","As high as possible","Repeated routinely","Unrelated to diagnosis"],0,"ALARA keeps exposure as low as reasonably achievable while meeting diagnostic needs.","ALARA ले diagnostic आवश्यकता पूरा गर्दै radiation exposure सम्भव भएसम्म कम राख्छ।"]},{"topic":"Dental Radiography & Photography","q":["A bitewing radiograph is especially useful for detecting:","Bitewing radiograph कुन कुरा पत्ता लगाउन उपयोगी हुन्छ?",["Interproximal caries and crestal bone levels","Root length of every tooth","TMJ disc position","Sinus infection only"],0,"Bitewings are commonly used to assess interproximal caries and alveolar crestal bone levels.","Bitewing ले interproximal caries र alveolar crestal bone level हेर्न मद्दत गर्छ।"]},{"topic":"Dental Radiography & Photography","q":["Radiographs should be taken:","Radiograph कहिले लिनुपर्छ?",["When individually justified by clinical need","At every visit automatically","Only for decoration","Whenever the operator is bored"],0,"Radiographs require individual clinical justification and should not be taken routinely without indication.","Radiograph व्यक्तिगत clinical आवश्यकता र औचित्यका आधारमा मात्र लिनुपर्छ।"]},{"topic":"Dental Radiography & Photography","q":["The main purpose of a paralleling technique is to:","Paralleling technique को मुख्य उद्देश्य के हो?",["Reduce image distortion","Increase magnification","Avoid receptor placement","Replace infection control"],0,"The paralleling technique helps produce geometrically accurate intraoral images.","Paralleling technique ले ज्यामितीय रूपमा सही intraoral image बनाउन मद्दत गर्छ।"]},{"topic":"Dental Radiography & Photography","q":["Before taking a dental photograph, obtain:","Dental photograph लिनुअघि के लिनुपर्छ?",["Appropriate informed consent","Only verbal permission from another patient","No permission ever","Consent after public posting"],0,"Obtain and document appropriate consent, especially for storage or sharing of identifiable images.","पहिचान खुल्ने फोटो राख्न वा साझा गर्नुअघि उपयुक्त सहमति लिनु र अभिलेख गर्नु आवश्यक छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["A drug used to reduce pain is called an:","दुखाइ कम गर्ने औषधिलाई के भनिन्छ?",["Analgesic","Antacid","Antifungal","Anticoagulant"],0,"Analgesics are medicines used to relieve pain.","Analgesic दुखाइ कम गर्न प्रयोग हुने औषधि हो।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["Antibiotics are effective against:","Antibiotic कुनविरुद्ध प्रभावकारी हुन्छ?",["Susceptible bacterial infections","All viral infections","All pain conditions","Dental calculus"],0,"Antibiotics act against susceptible bacteria and are not effective against viruses.","Antibiotic संवेदनशील bacteria विरुद्ध काम गर्छ; virus विरुद्ध प्रभावकारी हुँदैन।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["Before administering or recommending a medicine, check:","औषधि दिनु वा सिफारिस गर्नुअघि के जाँच्नुपर्छ?",["Allergies, medical history and current medicines","Only the patient's age","Only tooth number","Only appointment time"],0,"Allergies, conditions, interactions and contraindications are essential safety checks.","Allergy, रोग, औषधिको interaction र contraindication सुरक्षा जाँचका मुख्य भाग हुन्।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["Local anaesthetics mainly block:","Local anaesthetic ले मुख्यतया के block गर्छ?",["Voltage-gated sodium channels","Salivary ducts","Enamel rods","Red blood cell production"],0,"Blocking voltage-gated sodium channels prevents nerve impulse conduction.","Voltage-gated sodium channel रोक्दा nerve impulse सञ्चालन रोकिन्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["Xerostomia means:","Xerostomia को अर्थ के हो?",["Subjective sensation of dry mouth","Excessive tooth mobility","Bleeding gums","Bad breath only"],0,"Xerostomia is the subjective feeling of dry mouth and may be associated with reduced salivary flow.","Xerostomia भनेको मुख सुकेको अनुभूति हो र saliva कम हुनु यससँग सम्बन्धित हुन सक्छ।"]},{"topic":"Food & Nutrition","q":["Frequent intake of fermentable carbohydrates increases risk of:","Fermentable carbohydrate बारम्बार सेवन गर्दा कुन जोखिम बढ्छ?",["Dental caries","Enamel regeneration","Periodontal ligament growth","Tooth eruption"],0,"Frequent fermentable carbohydrate exposure leads to repeated plaque acid production and caries risk.","Fermentable carbohydrate बारम्बार सेवन गर्दा plaque मा acid उत्पादन दोहोरिएर caries जोखिम बढ्छ।"]},{"topic":"Food & Nutrition","q":["Vitamin C deficiency may cause:","Vitamin C को कमीले के हुन सक्छ?",["Gingival bleeding and impaired wound healing","Dental fluorosis","Enamel hyperplasia","Increased saliva only"],0,"Vitamin C is important for collagen; deficiency can affect gingiva and wound healing.","Vitamin C collagen का लागि आवश्यक हुन्छ; कमीले gingiva र घाउ निको हुने प्रक्रियामा असर गर्न सक्छ।"]},{"topic":"Food & Nutrition","q":["A balanced diet should include:","सन्तुलित आहारमा के समावेश हुनुपर्छ?",["Variety of nutrient-rich foods","Only sugary drinks","Only refined carbohydrates","No fruits or vegetables"],0,"A balanced diet provides appropriate macro- and micronutrients from varied foods.","सन्तुलित आहारले विभिन्न खाद्य पदार्थबाट आवश्यक macro र micronutrients दिन्छ।"]},{"topic":"Food & Nutrition","q":["Calcium and vitamin D are important for:","Calcium र vitamin D केका लागि महत्त्वपूर्ण छन्?",["Bone and tooth mineralization","Plaque staining","Bacterial growth","Tooth discoloration"],0,"Calcium and vitamin D support mineralization and skeletal health.","Calcium र vitamin D ले mineralization र हड्डीको स्वास्थ्यमा सहयोग गर्छन्।"]},{"topic":"Food & Nutrition","q":["The best general dietary advice for caries prevention is to:","Caries रोकथामका लागि सामान्य आहार सल्लाह कुन हो?",["Reduce frequency of free-sugar intake","Sip sweetened drinks throughout the day","Eat sticky sweets between every meal","Replace water with soft drinks"],0,"Reducing the frequency of free-sugar intake lowers repeated acid challenges.","Free sugar सेवनको आवृत्ति घटाउँदा बारम्बार हुने acid attack कम हुन्छ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["Incidence refers to:","Incidence भन्नाले के बुझिन्छ?",["New cases occurring in a population over a specified period","All existing cases at one point","Total number of hospitals","Number of health workers"],0,"Incidence measures new cases arising in a population at risk over time.","Incidence ले जोखिममा रहेको जनसंख्यामा निश्चित अवधिमा देखा परेका नयाँ case मापन गर्छ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["Prevalence refers to:","Prevalence भन्नाले के बुझिन्छ?",["Existing cases in a population at a specified time or period","Only new cases","Only deaths","Only treatment costs"],0,"Prevalence describes the proportion of a population with a condition at a given time or period.","Prevalence ले निश्चित समयमा वा अवधिमा रोग भएका व्यक्तिको अनुपात जनाउँछ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["DMFT index records:","DMFT index ले के अभिलेख गर्छ?",["Decayed, missing and filled permanent teeth","Daily mouth fluid temperature","Dental muscle function test","Only periodontal pockets"],0,"DMFT summarizes decayed, missing due to caries and filled permanent teeth.","DMFT ले caries का कारण कुहिएका, हराएका र भरिएका स्थायी दाँतको अवस्था देखाउँछ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["A case definition is used to:","Case definition किन प्रयोग गरिन्छ?",["Apply consistent criteria to identify cases","Choose clinic paint","Replace data analysis","Avoid diagnosis"],0,"A standardized case definition improves consistency in surveillance and surveys.","Standardized case definition ले surveillance र survey मा एकरूपता ल्याउँछ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["A useful first step in community diagnosis is to:","Community diagnosis को उपयोगी पहिलो चरण के हो?",["Collect and review relevant community data","Start treatment without assessment","Assume all communities are identical","Ignore local priorities"],0,"Community diagnosis begins with gathering and analyzing information about needs, resources and risks.","Community diagnosis मा आवश्यकता, स्रोत र जोखिमबारे जानकारी संकलन र विश्लेषण गरिन्छ।"]},{"topic":"Dental Ethics & Practice Management","q":["Informed consent should be:","Informed consent कस्तो हुनुपर्छ?",["Voluntary and based on adequate information","Obtained by force","A signature without explanation","Given by an unrelated person"],0,"Valid consent requires information, understanding, voluntariness and decision-making capacity.","वैध सहमतिका लागि जानकारी, बुझाइ, स्वेच्छा र निर्णय क्षमता आवश्यक हुन्छ।"]},{"topic":"Dental Ethics & Practice Management","q":["Patient records should be:","बिरामीको record कस्तो हुनुपर्छ?",["Accurate, timely and confidential","Changed to hide errors","Shared publicly","Written only from memory much later"],0,"Clinical records should be factual, timely, complete and securely stored.","Clinical record तथ्यपरक, समयमै, पूर्ण र सुरक्षित राखिनुपर्छ।"]},{"topic":"Dental Ethics & Practice Management","q":["A dental hygienist should perform only tasks:","Dental hygienist ले कस्ता काम मात्र गर्नुपर्छ?",["Within their education, competence and authorized scope","Requested by anyone regardless of competence","Seen on social media","Outside all regulations"],0,"Practitioners must work within their competence and legally authorized scope.","आफ्नो क्षमता र कानुनी रूपमा स्वीकृत कार्यक्षेत्रभित्र रहेर काम गर्नुपर्छ।"]},{"topic":"Dental Ethics & Practice Management","q":["Confidential patient information may be disclosed:","बिरामीको गोप्य जानकारी कहिले खुलाउन मिल्छ?",["With appropriate consent or lawful justification","To anyone who asks","On social media for teaching without safeguards","To other patients"],0,"Disclosure requires proper authorization or a lawful basis, following privacy rules.","उचित अनुमति वा कानुनी आधार र गोपनीयता नियमअनुसार मात्र जानकारी खुलाउन मिल्छ।"]},{"topic":"Dental Ethics & Practice Management","q":["When an error occurs, the professional should:","काममा गल्ती भएमा professional ले के गर्नुपर्छ?",["Act to protect the patient, report appropriately and document honestly","Hide it","Alter records","Blame the patient"],0,"Patient safety, appropriate disclosure/reporting and accurate documentation are essential.","बिरामीको सुरक्षा, उचित जानकारी/रिपोर्ट र सही अभिलेख महत्त्वपूर्ण हुन्छ।"]},{"topic":"Infection Prevention & Sterilization","q":["The first step in processing reusable dental instruments is generally:","पुनःप्रयोग हुने dental instrument प्रशोधनको पहिलो चरण के हो?",["Cleaning","Packaging","Storage","Lubrication only"],0,"Cleaning removes soil and organic material before inspection, packaging and sterilization.","Inspection, packaging र sterilization अघि cleaning ले फोहोर र जैविक पदार्थ हटाउँछ।"]},{"topic":"Infection Prevention & Sterilization","q":["Standard precautions should be applied to:","Standard precautions कसमा लागू गर्नुपर्छ?",["All patients","Only patients with known infections","Only surgical patients","Only children"],0,"Standard precautions apply to every patient, regardless of known infection status.","संक्रमण थाहा भए/नभए पनि सबै बिरामीमा standard precautions लागू हुन्छ।"]},{"topic":"Infection Prevention & Sterilization","q":["A biological indicator for sterilization commonly contains:","Sterilization को biological indicator मा के हुन्छ?",["Highly resistant bacterial spores","Blood cells","Saliva enzymes","Dental plaque"],0,"Biological indicators use resistant spores to monitor sterilization effectiveness.","Biological indicator ले sterilization को प्रभावकारिता जाँच्न resistant spores प्रयोग गर्छ।"]},{"topic":"Infection Prevention & Sterilization","q":["Used needles should be discarded:","प्रयोग भएका needle कसरी फाल्नुपर्छ?",["Immediately into an approved sharps container","Into general waste","After recapping with two hands","On the instrument tray"],0,"Dispose of sharps immediately in an approved puncture-resistant sharps container.","Sharps तुरुन्तै स्वीकृत puncture-resistant container मा फाल्नुपर्छ।"]},{"topic":"Infection Prevention & Sterilization","q":["Hand hygiene is required:","Hand hygiene कहिले आवश्यक हुन्छ?",["Before and after patient contact and at indicated moments","Only when hands look dirty","Only after lunch","Only at the end of the day"],0,"Hand hygiene at recommended moments is essential even when gloves are worn.","Gloves लगाएको अवस्थामा पनि तोकिएका समयमा hand hygiene आवश्यक हुन्छ।"]},{"topic":"Medical Emergencies & First Aid","q":["If a patient becomes unresponsive and is not breathing normally, the team should:","बिरामी अचेत भई सामान्य सास नफेरेमा के गर्नुपर्छ?",["Activate emergency response, obtain AED and start BLS","Continue dental treatment","Offer oral water","Wait for spontaneous recovery"],0,"Activate emergency response, obtain an AED and begin CPR according to current BLS training.","Emergency response सक्रिय गरी AED मगाउनुहोस् र हालको BLS तालिमअनुसार CPR सुरु गर्नुहोस्।"]},{"topic":"Medical Emergencies & First Aid","q":["A patient with suspected hypoglycaemia who is fully conscious and can swallow safely may need:","Hypoglycaemia शंका भएको पूर्ण होसमा र निल्न सक्ने बिरामीलाई के आवश्यक पर्न सक्छ?",["Fast-acting oral glucose according to protocol","Nothing by mouth in every case","An antibiotic","Immediate extraction"],0,"Follow the clinic protocol; oral glucose may be appropriate if the patient is fully conscious and can swallow.","Clinic protocol पालना गर्नुहोस्; पूर्ण होसमा र निल्न सक्ने भए oral glucose उपयुक्त हुन सक्छ।"]},{"topic":"Medical Emergencies & First Aid","q":["The first priority during any medical emergency is to:","कुनै पनि medical emergency मा पहिलो प्राथमिकता के हो?",["Ensure scene safety and assess the patient","Continue the procedure","Leave the patient alone","Give medication without assessment"],0,"Ensure safety, assess responsiveness and activate appropriate emergency help.","स्थान सुरक्षित गरी बिरामीको अवस्था जाँच्नुहोस् र आवश्यक emergency सहायता बोलाउनुहोस्।"]},{"topic":"Medical Emergencies & First Aid","q":["An AED should be used:","AED कहिले प्रयोग गर्नुपर्छ?",["As soon as available in suspected cardiac arrest, following prompts","Only after 30 minutes","Only on conscious patients","Instead of calling emergency services"],0,"Use the AED as soon as available and follow its prompts while CPR continues.","AED उपलब्ध हुनासाथ प्रयोग गरी निर्देशन पालना गर्दै CPR जारी राख्नुहोस्।"]},{"topic":"Medical Emergencies & First Aid","q":["If a patient faints in the dental chair, the operator should first:","Dental chair मा बिरामी बेहोस भएमा पहिलो कदम के हो?",["Stop treatment, protect the patient and assess airway and breathing","Ask the patient to stand quickly","Continue scaling","Give food immediately"],0,"Stop treatment, prevent injury, position safely and assess airway, breathing and circulation.","उपचार रोक्नुहोस्, चोटबाट जोगाउनुहोस्, सुरक्षित position मा राखेर ABC जाँच्नुहोस्।"]}];
 const mcqBank=bank.slice(0,Math.ceil(bank.length/2));
 const mockBank=bank.slice(Math.ceil(bank.length/2));
 const root=document.getElementById("nhpcMcqArea");
 if(!root) return;
 let topic="सबै विषय",index=0,answers={};
 const topics=["सबै विषय",...["Basic Periodontology","Oral Pathology & Microbiology","Dental Materials, Instruments & Assisting","Oral Anatomy & Physiology","Dental Public Health & Community Dentistry","Dental Radiography & Photography","Dental Pharmacy & Pharmacology","Food & Nutrition","Epidemiology & Community Diagnosis","Dental Ethics & Practice Management","Infection Prevention & Sterilization","Medical Emergencies & First Aid"]];
 const filtered=()=>topic==="सबै विषय"?mcqBank:mcqBank.filter(x=>x.topic===topic);
 function render(){
  const list=filtered(),item=list[index]; if(!item)return;
  const q=item.q,key=topic+"-"+index,chosen=answers[key];
  root.querySelector("#nhpcMcqCount").textContent=(index+1)+" / "+list.length;
  root.querySelector("#nhpcQuestion").innerHTML=`<article class="question"><div class="qtop"><span>NHPC PRACTICE • QUESTION ${index+1}</span><span>${chosen===undefined?"Not answered":"Answered"}</span></div><h3>${q[0]}</h3><p class="translation">${q[1]}</p><div class="options">${q[2].map((o,i)=>`<button class="option ${chosen!==undefined&&i===q[3]?"correct":chosen===i?"wrong":""}" data-answer="${i}" ${chosen!==undefined?"disabled":""}>${String.fromCharCode(65+i)}. ${o}</button>`).join("")}</div>${chosen!==undefined?`<div class="feedback ${chosen===q[3]?"good":"bad"}"><b>${chosen===q[3]?"सही उत्तर!":"सही उत्तर: "+q[2][q[3]]}</b><p>${q[4]}</p><p>${q[5]}</p></div>`:""}<div class="nextrow"><button class="smallbtn" id="nhpcPrev" ${index===0?"disabled":""}>अघिल्लो</button><button class="smallbtn" id="nhpcNext">${index===list.length-1?"फेरि सुरु":"अर्को प्रश्न"}</button></div></article>`;
  root.querySelectorAll("[data-answer]").forEach(b=>b.addEventListener("click",()=>{if(answers[key]!==undefined)return;answers[key]=Number(b.dataset.answer);render()}));
  root.querySelector("#nhpcPrev").addEventListener("click",()=>{index=Math.max(0,index-1);render()});
  root.querySelector("#nhpcNext").addEventListener("click",()=>{index=index===list.length-1?0:index+1;render()});
 }
 function show(){
  root.innerHTML=`<div class="section-head"><div><p class="eyebrow">NHPC QUESTION BANK</p><h3>विषयगत MCQ अभ्यास</h3></div><span class="pill">60 Questions</span></div><p class="muted">१२ विषयका ६० अभ्यास प्रश्न। उत्तर छानेपछि सही उत्तर र व्याख्या देखिन्छ।</p><div class="dha-mcq-filters" id="nhpcFilters">${topics.map((t,i)=>`<button type="button" class="smallbtn ${i===0?"active":""}" data-topic="${t}">${i===0?"सबै विषय":t}</button>`).join("")}</div><div class="section-head"><span class="pill" id="nhpcMcqCount"></span></div><div id="nhpcQuestion"></div>`;
  root.querySelector("#nhpcFilters").addEventListener("click",e=>{const b=e.target.closest("[data-topic]");if(!b)return;topic=b.dataset.topic;index=0;root.querySelectorAll("[data-topic]").forEach(x=>x.classList.toggle("active",x===b));render()});
  render();
 }
 document.getElementById("nhpcStartMcq")?.addEventListener("click",()=>{root.classList.remove("hidden");document.getElementById("nhpcCloseMcq")?.classList.remove("hidden");show();root.scrollIntoView({behavior:"smooth",block:"start"})});
 document.getElementById("nhpcCloseMcq")?.addEventListener("click",()=>{root.classList.add("hidden");document.getElementById("nhpcCloseMcq")?.classList.add("hidden")});


 // NHPC detailed bilingual study notes: independent learning resource.
 const nhpcNotes=[["Basic Periodontology",[["Periodontium and its functions","The periodontium consists of gingiva, periodontal ligament, cementum and alveolar bone. It supports teeth, absorbs occlusal forces and maintains tooth attachment.","Periodontium का चार भाग gingiva, periodontal ligament, cementum र alveolar bone हुन्। यसले दाँतलाई अड्याउने, चपाउँदाको बल सहने र दाँतको support कायम राख्ने काम गर्छ।","Clinical focus: Identify all four tissues and assess probing depth, bleeding, recession and mobility."],["Gingivitis and periodontitis","Plaque-induced gingivitis is inflammation without periodontal attachment loss and is generally reversible. Periodontitis involves loss of attachment and supporting bone. Smoking, diabetes and poor plaque control modify risk.","Gingivitis मा गिजा सुन्निन्छ तर periodontal attachment loss हुँदैन र राम्रो plaque control ले सुधार हुन सक्छ। Periodontitis मा attachment र supporting bone क्षति हुन्छ। धूम्रपान, diabetes र कमजोर plaque control जोखिम बढाउने कारक हुन्।","Clinical focus: Do not diagnose periodontitis from bleeding alone; assess clinical attachment level and radiographic findings when indicated."]]],["Oral Pathology & Microbiology",[["Dental caries and biofilm","Dental caries is a biofilm-mediated, sugar-driven, multifactorial disease. Frequent fermentable carbohydrate exposure promotes acid production and mineral loss. Saliva and fluoride support remineralization.","Dental caries biofilm, चिनी र अन्य host/environmental factors सँग सम्बन्धित रोग हो। पटक-पटक चिनी खाँदा acid उत्पादन बढेर दाँतको mineral घट्छ। Saliva र fluoride ले remineralization मा सहयोग गर्छन्।","Clinical focus: Assess diet frequency, plaque, fluoride exposure and caries risk; reinforce prevention."],["Oral lesions and infection","Common oral conditions include candidiasis, recurrent aphthous ulcers, herpes-related lesions and traumatic ulcers. A persistent, indurated, unexplained ulcer or suspicious red/white lesion needs prompt professional assessment and referral.","मुखमा candidiasis, aphthous ulcer, herpes सम्बन्धित घाउ र चोटका ulcer देखिन सक्छन्। लामो समय निको नभएको, कडा किनारा भएको वा शंकास्पद रातो/सेतो घाउ भए तुरुन्त दन्त चिकित्सकबाट जाँच र आवश्यक referral गर्नुपर्छ।","Clinical focus: Record site, size, duration and appearance; never delay referral for a suspicious lesion."]]],["Dental Materials & Instruments",[["Dental material properties","Important properties include strength, hardness, setting time, dimensional stability, solubility and biocompatibility. Material selection depends on indication, moisture control, handling and manufacturer instructions.","मुख्य गुणहरूमा strength, hardness, setting time, dimensional stability, solubility र biocompatibility पर्छन्। कुन material प्रयोग गर्ने भन्ने कुरा उपचारको आवश्यकता, moisture control र manufacturer को निर्देशनमा निर्भर हुन्छ।","Clinical focus: Check expiry, storage, mixing ratio and manufacturer instructions before use."],["Instruments and ergonomics","A mouth mirror provides indirect vision and retraction; a periodontal probe measures sulcus or pocket depth; scalers and curettes remove deposits. Correct grasp, fulcrum and operator posture improve control and reduce injury.","Mouth mirror ले indirect vision र retraction दिन्छ; periodontal probe ले sulcus/pocket depth नाप्छ; scaler र curette ले deposit हटाउँछन्। सही grasp, fulcrum र posture ले काम सुरक्षित र प्रभावकारी बनाउँछन्।","Clinical focus: Select the correct instrument and maintain a stable fulcrum; avoid excessive force."]]],["Oral Anatomy & Physiology",[["Tooth structure and dentition","A tooth has crown, neck and root. Enamel covers the anatomical crown; dentin forms most of the tooth; pulp contains nerves and blood vessels; cementum covers the root. Primary dentition has 20 teeth and permanent dentition usually has 32 including third molars.","दाँतका crown, neck र root हुन्छन्। Enamel ले crown ढाक्छ, dentin ले धेरै भाग बनाउँछ, pulp मा nerve र blood vessel हुन्छन् र cementum ले root ढाक्छ। दूध दाँत २० र स्थायी दाँत सामान्यतया wisdom teeth सहित ३२ हुन्छन्।","Clinical focus: Know tooth surfaces, numbering, eruption patterns and differences between primary and permanent teeth."],["Saliva and oral functions","Saliva lubricates oral tissues, aids swallowing and speech, buffers acids, clears food debris and contributes antimicrobial protection and remineralization. Reduced salivary flow increases caries and mucosal discomfort risk.","लारले मुख ओसिलो राख्छ, निल्न र बोल्न सहयोग गर्छ, acid neutralize गर्छ, food debris हटाउँछ र antimicrobial protection तथा remineralization मा सहयोग गर्छ। लार कम हुँदा caries र मुख सुक्ने समस्या बढ्न सक्छ।","Clinical focus: Ask about dry mouth, medicines and hydration; assess caries risk."]]],["Dental Public Health",[["Prevention and health promotion","Primary prevention aims to prevent disease before it occurs, such as fluoride use and oral health education. Secondary prevention emphasizes early detection and timely intervention. Tertiary prevention limits complications and restores function.","Primary prevention ले रोग हुनुअघि रोक्छ, जस्तै fluoride र oral health education। Secondary prevention ले रोग चाँडै पत्ता लगाएर उपचार गर्छ। Tertiary prevention ले जटिलता घटाई कार्यक्षमता सुधार्छ।","Clinical focus: Tailor oral health education to age, literacy, culture and individual risk."],["Community oral health programmes","Community programmes begin with needs assessment, clear objectives, planning, implementation, monitoring and evaluation. School programmes may include supervised brushing, fluoride interventions and referral pathways.","समुदायमा कार्यक्रम सुरु गर्दा आवश्यकता पहिचान, उद्देश्य निर्धारण, योजना, कार्यान्वयन, अनुगमन र मूल्याङ्कन गर्नुपर्छ। विद्यालय कार्यक्रममा supervised brushing, fluoride कार्यक्रम र referral व्यवस्था हुन सक्छ।","Clinical focus: Record coverage, participation, outcomes and follow-up rather than only activities."]]],["Dental Radiography & Photography",[["Radiation protection","Use radiographs only when clinically justified. Apply ALARA/ALADA principles, optimize exposure settings, use appropriate collimation and positioning, and follow current local radiation safety requirements. Avoid repeat exposures through careful technique.","आवश्यक clinical कारण हुँदा मात्र X-ray लिनुपर्छ। ALARA/ALADA सिद्धान्त अपनाउने, सही exposure setting र positioning गर्ने तथा स्थानीय radiation safety नियम पालना गर्ने। सही technique ले दोहोर्‍याएर X-ray लिनुपर्ने अवस्था घटाउँछ।","Clinical focus: Confirm indication, patient identity and correct image receptor placement before exposure."],["Image quality and documentation","Diagnostic images should show the required anatomy with appropriate density, contrast, sharpness and minimal distortion. Clinical photographs require consent, secure storage and consistent views when used for monitoring.","Diagnostic image मा आवश्यक anatomy स्पष्ट, उचित density/contrast/sharpness र न्यून distortion हुनुपर्छ। Clinical photo खिच्दा consent, सुरक्षित storage र monitoring का लागि मिल्दोजुल्दो view आवश्यक हुन्छ।","Clinical focus: Follow infection control for sensors and maintain patient confidentiality."]]],["Dental Pharmacy",[["Safe medication practice","Check the medication name, indication, dose, route, timing, allergies, contraindications and relevant medical history. Follow the prescriber’s instructions and local scope-of-practice rules; do not prescribe outside authorization.","औषधिको नाम, कारण, मात्रा, दिने बाटो, समय, allergy, contraindication र medical history जाँच्नुपर्छ। Prescriber को निर्देशन र आफ्नो professional scope पालना गर्नुपर्छ; अधिकारबाहिर औषधि prescribe गर्नु हुँदैन।","Clinical focus: Clarify allergies and current medicines; document and report adverse reactions."],["Local anaesthesia and emergencies","Before local anaesthesia, review medical history, allergies, medications and relevant precautions. Recognize early signs of adverse reactions or toxicity and activate the clinic emergency protocol; maintain appropriate emergency equipment and training.","Local anaesthesia अघि medical history, allergy, औषधि र आवश्यक सावधानी बुझ्नुपर्छ। Adverse reaction वा toxicity का प्रारम्भिक संकेत चिन्नु र clinic emergency protocol सुरु गर्नु आवश्यक हुन्छ।","Clinical focus: Never exceed authorized duties; know emergency response roles and escalation steps."]]],["Food and Nutrition",[["Diet and oral health","Frequency of free-sugar intake is an important caries risk factor. Encourage water, balanced meals and limiting sugary snacks and drinks between meals. Nutritional advice should be practical and culturally appropriate.","Free sugar कति पटक खाइन्छ भन्ने कुरा caries risk का लागि महत्त्वपूर्ण हुन्छ। पानी, सन्तुलित खाना र खानाबीच मीठा snacks/drinks कम गर्न प्रोत्साहन गर्नुपर्छ। पोषण सल्लाह व्यवहारिक र स्थानीय खानासँग मिल्ने हुनुपर्छ।","Clinical focus: Ask about frequency and timing of sugar exposure, not only total quantity."],["Nutrients and oral tissues","Protein supports tissue growth and repair; calcium and phosphorus contribute to mineralized tissues; vitamin D supports calcium regulation; vitamin C is important for collagen formation. Deficiency may affect oral and general health.","Protein ले tissue growth र repair मा सहयोग गर्छ; calcium र phosphorus mineralized tissue का लागि, vitamin D calcium regulation का लागि र vitamin C collagen बनाउन महत्त्वपूर्ण हुन्छ। कमी हुँदा मुख र समग्र स्वास्थ्यमा असर पर्न सक्छ।","Clinical focus: Refer suspected nutritional deficiency for appropriate medical or nutrition assessment."]]],["Epidemiology & Community Diagnosis",[["Basic epidemiological measures","Incidence measures new cases arising in a population at risk over a specified period. Prevalence measures all existing cases at a particular time or over a period. A clear numerator, denominator and time frame are essential.","Incidence ले निश्चित समयमा नयाँ रोगी कति थपिए भन्ने जनाउँछ। Prevalence ले कुनै समय वा अवधिमा रहेका सबै रोगी जनाउँछ। Numerator, denominator र समय स्पष्ट हुनुपर्छ।","Clinical focus: Check the population, case definition and time period before interpreting a rate."],["Community diagnosis and survey","A community diagnosis identifies oral health needs, determinants, available resources and priority groups. A survey requires a defined objective, sampling approach, standardized examination criteria, ethical consent and reliable data recording.","Community diagnosis ले मुख स्वास्थ्य आवश्यकता, कारण, उपलब्ध स्रोत र प्राथमिक समूह पहिचान गर्छ। Survey गर्दा स्पष्ट उद्देश्य, sampling, standard examination criteria, ethical consent र सही data recording आवश्यक हुन्छ।","Clinical focus: Use findings to set measurable priorities and evaluate programme impact."]]],["Dental Ethics & Practice Management",[["Consent and confidentiality","Valid informed consent requires understandable information about the proposed procedure, benefits, material risks and alternatives, with an opportunity to ask questions and decide voluntarily. Protect patient records and share information only with proper authorization or legal basis.","सही informed consent का लागि उपचार, फाइदा, जोखिम र विकल्प बुझिने भाषामा बताउनुपर्छ। बिरामीलाई प्रश्न गर्ने र स्वेच्छाले निर्णय गर्ने अवसर दिनुपर्छ। Patient record गोप्य राख्नुपर्छ।","Clinical focus: Document consent, refusal, relevant discussions and authorized disclosures."],["Professional conduct and records","Work within competence and legal scope, maintain accurate contemporaneous records, follow infection prevention policies, communicate respectfully and refer when a case exceeds competence.","आफ्नो सीप र कानुनी कार्यक्षेत्रभित्र काम गर्ने, समयमै सही record राख्ने, infection prevention पालना गर्ने, सम्मानपूर्वक संवाद गर्ने र आफ्नो क्षमताभन्दा बाहिरको समस्या referral गर्ने।","Clinical focus: Never alter records retrospectively without a transparent dated correction."]]],["Infection Prevention & Sterilization",[["Standard precautions","Treat blood and body fluids as potentially infectious. Perform hand hygiene, use appropriate PPE, practice safe sharps handling, clean and disinfect environmental surfaces, and reprocess reusable instruments according to validated instructions.","रगत र शरीरका तरल पदार्थलाई सम्भावित संक्रमणयुक्त मानेर सावधानी अपनाउनुपर्छ। Hand hygiene, PPE, sharps safety, सतह सफाइ र reusable instruments को सही reprocessing आवश्यक हुन्छ।","Clinical focus: Use a puncture-resistant sharps container and never recap needles with two hands."],["Instrument reprocessing","Reusable critical instruments that penetrate soft tissue or bone require cleaning followed by validated sterilization. Monitor sterilization cycles with physical, chemical and biological indicators as required by policy; store packs dry and intact.","Soft tissue वा bone छेड्ने reusable critical instrument सफा गरेपछि validated sterilization गर्नुपर्छ। नीति अनुसार physical, chemical र biological indicator प्रयोग गरी cycle monitor गर्नुपर्छ। Pack सुक्खा र नफुटेको अवस्थामा राख्नुपर्छ।","Clinical focus: A failed indicator or compromised pack means the instruments must not be considered sterile."]]],["Medical Emergencies & First Aid",[["Recognition and initial response","Recognize deterioration early, stop dental treatment, call for help, assess responsiveness and breathing, and activate the clinic emergency plan. Provide basic life support within current training and local protocol.","अवस्था बिग्रिएको चाँडै चिन्नु, उपचार रोक्नु, सहयोग बोलाउनु, responsiveness र breathing जाँच्नु र clinic emergency plan सुरु गर्नु। आफ्नो तालिम र स्थानीय protocol अनुसार BLS दिनुपर्छ।","Clinical focus: Ensure emergency numbers, oxygen/AED where available, and team roles are known."],["Syncope and anaphylaxis","For suspected syncope, stop treatment, position the patient safely and assess airway, breathing and circulation. Suspected anaphylaxis is a life-threatening emergency requiring immediate emergency activation and prompt intramuscular adrenaline by trained authorized personnel according to protocol.","Syncope शंका भए उपचार रोक्ने, बिरामीलाई सुरक्षित position मा राख्ने र airway, breathing, circulation जाँच्ने। Anaphylaxis जीवन-जोखिमयुक्त emergency हो; तुरुन्त सहायता बोलाई तालिमप्राप्त अधिकृत व्यक्तिले protocol अनुसार IM adrenaline दिनुपर्छ।","Clinical focus: Do not delay emergency transfer or treatment while waiting for symptoms to resolve."]]]];
 const notesRoot=document.getElementById("nhpcNotesArea");
 function renderNhpcNotes(){
  notesRoot.classList.remove("hidden");
  document.getElementById("nhpcCloseNotes")?.classList.remove("hidden");
  document.getElementById("nhpcMcqArea")?.classList.add("hidden");
  document.getElementById("nhpcFullMock")?.classList.add("hidden");
  document.getElementById("nhpcCloseMcq")?.classList.add("hidden");
  document.getElementById("nhpcCloseMock")?.classList.add("hidden");
  notesRoot.innerHTML=`<div class="section-head"><div><p class="eyebrow">BILINGUAL STUDY LIBRARY</p><h3>NHPC Detailed Study Notes</h3></div><span class="pill">१२ विषय</span></div><p class="muted">प्रत्येक विषयमा English concept, नेपाली व्याख्या र Clinical focus समावेश गरिएको छ।</p><div class="dha-mcq-filters" id="nhpcNotesFilters">${nhpcNotes.map((t,i)=>`<button class="smallbtn ${i===0?"active":""}" data-notes-topic="${i}" type="button">${t[0]}</button>`).join("")}</div><div id="nhpcNotesContent"></div>`;
  const showTopic=i=>{const t=nhpcNotes[i];notesRoot.querySelectorAll("[data-notes-topic]").forEach(b=>b.classList.toggle("active",Number(b.dataset.notesTopic)===i));notesRoot.querySelector("#nhpcNotesContent").innerHTML=`<h3>${t[0]}</h3><div class="notes-list">${t[1].map((n,j)=>`<article class="note"><h3>${j+1}. ${n[0]}</h3><p><b>English:</b> ${n[1]}</p><p class="np"><b>नेपाली:</b> ${n[2]}</p><div class="clinical-point"><b>Clinical focus:</b> ${n[3].replace("Clinical focus: ","")}</div></article>`).join("")}</div>`};
  notesRoot.querySelector("#nhpcNotesFilters").addEventListener("click",e=>{const b=e.target.closest("[data-notes-topic]");if(b)showTopic(Number(b.dataset.notesTopic))});showTopic(0);
  notesRoot.scrollIntoView({behavior:"smooth",block:"start"});
 }
 document.getElementById("nhpcStartNotes")?.addEventListener("click",renderNhpcNotes);
 document.getElementById("nhpcCloseNotes")?.addEventListener("click",()=>{notesRoot.classList.add("hidden");document.getElementById("nhpcCloseNotes")?.classList.add("hidden")});
 // NHPC student progress summary, based on locally saved mock-test attempts.
 function renderNhpcProgress(){
  const box=document.getElementById("nhpcProgress");if(!box)return;
  let rows=[];try{rows=JSON.parse(localStorage.getItem("dhpn-mock-history")||"[]")}catch(e){}
  rows=rows.filter(r=>(r.module||"").toLowerCase().includes("nhpc"));
  const avg=rows.length?Math.round(rows.reduce((s,r)=>s+r.percent,0)/rows.length):0,best=rows.length?Math.max(...rows.map(r=>r.percent)):0,last=rows.length?rows[rows.length-1]:null;
  box.innerHTML=`<div class="progress-mini-grid"><article><small>Mock Attempts</small><strong>${rows.length}</strong></article><article><small>Average Score</small><strong>${avg}%</strong></article><article><small>Best Score</small><strong>${best}%</strong></article></div><p class="muted">${last?"पछिल्लो अभ्यास: "+last.percent+"% • "+new Date(last.date).toLocaleDateString():"अहिलेसम्म NHPC Mock Test को नतिजा छैन। पहिलो परीक्षा दिएपछि यहाँ प्रगति देखिन्छ।"}</p>`;
 }
 renderNhpcProgress();
 // NHPC full-length practice mock: 50 questions, 60 minutes (independent practice format).
 const mockRoot=document.getElementById("nhpcFullMock");
 let mockSet=[],mockAt=0,mockPicked={},mockClock=null,mockSeconds=3600,mockDone=false;
 const shuffleItems=a=>[...a].sort(()=>Math.random()-.5);
 function openNhpcMock(){
  clearInterval(mockClock);mockClock=null;
  mockRoot.classList.remove("hidden");
  document.getElementById("nhpcCloseMock")?.classList.remove("hidden");
  document.getElementById("nhpcMcqArea")?.classList.add("hidden");
  document.getElementById("nhpcCloseMcq")?.classList.add("hidden");
  mockRoot.innerHTML=`<div class="section-head"><div><p class="eyebrow">NHPC EXAM SIMULATION</p><h3>Full Mock Test</h3></div><span class="pill">50 Questions</span></div>
   <div class="notice"><b>परीक्षा अभ्यासका नियम</b><p>५० प्रश्न • ६० मिनेट • प्रत्येक प्रश्न १ अंक। उत्तर अन्तिममा मात्र जाँचिन्छ। यो अभ्यासका लागि बनाइएको नमुना ढाँचा हो, NHPC को आधिकारिक परीक्षा ढाँचा होइन।</p></div>
   <button class="primary" id="nhpcBeginFull">परीक्षा सुरु गर्नुहोस्</button>`;
  mockRoot.scrollIntoView({behavior:"smooth",block:"start"});
  document.getElementById("nhpcBeginFull").addEventListener("click",beginNhpcMock);
 }
 function beginNhpcMock(){
  clearInterval(mockClock);mockSet=shuffleItems(mockBank).slice(0,Math.min(50,mockBank.length));mockAt=0;mockPicked={};mockSeconds=3600;mockDone=false;drawNhpcMock();
  mockClock=setInterval(()=>{mockSeconds--;const t=mockRoot.querySelector("#nhpcFullTimer");if(t)t.textContent=fmtNhpcTime();if(mockSeconds<=0)finishNhpcMock(true)},1000);
 }
 function fmtNhpcTime(){return Math.floor(mockSeconds/60)+":"+String(mockSeconds%60).padStart(2,"0")}
 function drawNhpcMock(){
  const item=mockSet[mockAt],q=item.q,selected=mockPicked[mockAt];
  mockRoot.innerHTML=`<div class="section-head"><div><p class="eyebrow">NHPC FULL MOCK TEST</p><h3>प्रश्न ${mockAt+1} / 50</h3></div><span class="timer" id="nhpcFullTimer">${fmtNhpcTime()}</span></div>
   <div class="mock-progress"><span style="width:${Object.keys(mockPicked).length/50*100}%"></span></div>
   <div class="mock-nav" aria-label="Question navigation">${mockSet.map((_,i)=>`<button type="button" class="${i===mockAt?"current":""} ${mockPicked[i]!==undefined?"answered":""}" data-jump="${i}">${i+1}</button>`).join("")}</div>
   <article class="question"><div class="qtop"><span>${item.topic}</span><span>${selected===undefined?"उत्तर छान्नुहोस्":"उत्तर सुरक्षित भयो"}</span></div><h3>${q[0]}</h3><p class="translation">${q[1]}</p><div class="options">${q[2].map((o,i)=>`<button type="button" class="option ${selected===i?"selected":""}" data-full-answer="${i}">${String.fromCharCode(65+i)}. ${o}</button>`).join("")}</div>
   <div class="nextrow"><button class="smallbtn" id="nhpcFullPrev" ${mockAt===0?"disabled":""}>अघिल्लो</button><span class="muted">${Object.keys(mockPicked).length}/50 उत्तर</span><button class="smallbtn" id="nhpcFullNext">${mockAt===49?"परीक्षा बुझाउनुहोस्":"अर्को"}</button></div></article>
   <div class="nextrow"><button class="secondary" id="nhpcFullSubmit">अहिले नै परीक्षा बुझाउनुहोस्</button></div>`;
  mockRoot.querySelectorAll("[data-full-answer]").forEach(b=>b.addEventListener("click",()=>{mockPicked[mockAt]=Number(b.dataset.fullAnswer);drawNhpcMock()}));
  mockRoot.querySelectorAll("[data-jump]").forEach(b=>b.addEventListener("click",()=>{mockAt=Number(b.dataset.jump);drawNhpcMock()}));
  mockRoot.querySelector("#nhpcFullPrev").addEventListener("click",()=>{mockAt=Math.max(0,mockAt-1);drawNhpcMock()});
  mockRoot.querySelector("#nhpcFullNext").addEventListener("click",()=>{if(mockAt===49)finishNhpcMock(false);else{mockAt++;drawNhpcMock()}});
  mockRoot.querySelector("#nhpcFullSubmit").addEventListener("click",()=>{if(confirm("परीक्षा बुझाउने हो? बाँकी अनुत्तरित प्रश्न गलत मानिनेछन्।"))finishNhpcMock(false)});
 }
 function finishNhpcMock(auto){
  if(mockDone)return;mockDone=true;clearInterval(mockClock);mockClock=null;
  const score=mockSet.reduce((sum,item,i)=>sum+(mockPicked[i]===item.q[3]?1:0),0);
  window.DHPNProgress?.recordMock?.("NHPC – Dental Hygienist",score,50);renderNhpcProgress();
  mockRoot.innerHTML=`<div class="result"><p>NHPC FULL MOCK COMPLETED</p><strong>${score}/50</strong><b>${score*2}%</b><p>${auto?"समय सकिएपछि परीक्षा स्वतः बुझाइयो।":"तपाईंको परीक्षा बुझाइयो।"} ${50-Object.keys(mockPicked).length} प्रश्न अनुत्तरित थिए।</p><p>${score>=40?"धेरै राम्रो प्रयास!":score>=25?"राम्रो प्रयास। कमजोर विषयहरू पुनः अध्ययन गर्नुहोस्।":"नोट्स पढेर फेरि अभ्यास गर्नुहोस्।"}</p><button class="primary" id="nhpcShowReview">उत्तर समीक्षा गर्नुहोस्</button> <button class="secondary" id="nhpcRetake">फेरि परीक्षा दिनुहोस्</button></div><div id="nhpcFullReview"></div>`;
  mockRoot.querySelector("#nhpcShowReview").addEventListener("click",()=>{mockRoot.querySelector("#nhpcFullReview").innerHTML=mockSet.map((item,i)=>{const q=item.q,ans=mockPicked[i];return `<article class="note"><p class="eyebrow">${i+1}. ${item.topic}</p><h3>${q[0]}</h3><p class="translation">${q[1]}</p><p>तपाईंको उत्तर: <b>${ans===undefined?"उत्तर नदिएको":q[2][ans]}</b></p><p>सही उत्तर: <b>${q[2][q[3]]}</b></p><p>${q[4]}</p><p class="np">${q[5]}</p><span class="pill">${ans===q[3]?"सही":"गलत / अनुत्तरित"}</span></article>`}).join("")});
  mockRoot.querySelector("#nhpcRetake").addEventListener("click",beginNhpcMock);
 }
 document.getElementById("nhpcStartFullMock")?.addEventListener("click",openNhpcMock);
 document.getElementById("nhpcCloseMock")?.addEventListener("click",()=>{clearInterval(mockClock);mockClock=null;mockRoot.classList.add("hidden");document.getElementById("nhpcCloseMock")?.classList.add("hidden")});


  if (window.DHPNRandomizeQuestionBank) window.DHPNRandomizeQuestionBank(bank);
})();